-- Gerado de SnapshotTables (MIG-01a, ADR 0017). Não edite à mão: rode o SnapshotScriptsTests com BQ_UPDATE_SNAPSHOT_SQL=1.
-- Uso: scripts/dolibarr-snapshot.sh (mariadb --batch --raw --skip-column-names, saída direto para o age).
SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
START TRANSACTION WITH CONSISTENT SNAPSHOT, READ ONLY;
SELECT CONCAT('INSERT INTO `bqe_snapshot` (`taken_at`) VALUES (', QUOTE(UTC_TIMESTAMP(6)), ');');
SELECT CONCAT('INSERT INTO `llx_const` (`name`, `value`, `entity`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`name` USING utf8mb4)), QUOTE(CONVERT(`value` USING utf8mb4)), QUOTE(CONVERT(`entity` USING utf8mb4))), ');') FROM `llx_const` WHERE name = 'MAIN_INFO_SIREN';
SELECT CONCAT('INSERT INTO `llx_societe` (`rowid`, `nom`, `name_alias`, `client`, `fournisseur`, `siren`, `siret`, `ape`, `idprof4`, `tva_intra`, `address`, `zip`, `town`, `fk_departement`, `fk_pays`, `phone`, `email`, `note_private`, `note_public`, `status`, `cond_reglement`, `fk_typent`, `entity`, `tms`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`rowid` USING utf8mb4)), QUOTE(CONVERT(`nom` USING utf8mb4)), QUOTE(CONVERT(`name_alias` USING utf8mb4)), QUOTE(CONVERT(`client` USING utf8mb4)), QUOTE(CONVERT(`fournisseur` USING utf8mb4)), QUOTE(CONVERT(`siren` USING utf8mb4)), QUOTE(CONVERT(`siret` USING utf8mb4)), QUOTE(CONVERT(`ape` USING utf8mb4)), QUOTE(CONVERT(`idprof4` USING utf8mb4)), QUOTE(CONVERT(`tva_intra` USING utf8mb4)), QUOTE(CONVERT(`address` USING utf8mb4)), QUOTE(CONVERT(`zip` USING utf8mb4)), QUOTE(CONVERT(`town` USING utf8mb4)), QUOTE(CONVERT(`fk_departement` USING utf8mb4)), QUOTE(CONVERT(`fk_pays` USING utf8mb4)), QUOTE(CONVERT(`phone` USING utf8mb4)), QUOTE(CONVERT(`email` USING utf8mb4)), QUOTE(CONVERT(`note_private` USING utf8mb4)), QUOTE(CONVERT(`note_public` USING utf8mb4)), QUOTE(CONVERT(`status` USING utf8mb4)), QUOTE(CONVERT(`cond_reglement` USING utf8mb4)), QUOTE(CONVERT(`fk_typent` USING utf8mb4)), QUOTE(CONVERT(`entity` USING utf8mb4)), QUOTE(CONVERT(`tms` USING utf8mb4))), ');') FROM `llx_societe`;
SELECT CONCAT('INSERT INTO `llx_socpeople` (`rowid`, `fk_soc`, `lastname`, `firstname`, `poste`, `email`, `phone`, `phone_mobile`, `address`, `zip`, `town`, `statut`, `entity`, `tms`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`rowid` USING utf8mb4)), QUOTE(CONVERT(`fk_soc` USING utf8mb4)), QUOTE(CONVERT(`lastname` USING utf8mb4)), QUOTE(CONVERT(`firstname` USING utf8mb4)), QUOTE(CONVERT(`poste` USING utf8mb4)), QUOTE(CONVERT(`email` USING utf8mb4)), QUOTE(CONVERT(`phone` USING utf8mb4)), QUOTE(CONVERT(`phone_mobile` USING utf8mb4)), QUOTE(CONVERT(`address` USING utf8mb4)), QUOTE(CONVERT(`zip` USING utf8mb4)), QUOTE(CONVERT(`town` USING utf8mb4)), QUOTE(CONVERT(`statut` USING utf8mb4)), QUOTE(CONVERT(`entity` USING utf8mb4)), QUOTE(CONVERT(`tms` USING utf8mb4))), ');') FROM `llx_socpeople`;
SELECT CONCAT('INSERT INTO `llx_c_payment_term` (`rowid`, `code`, `libelle`, `nbjour`, `type_cdr`, `decalage`, `active`, `entity`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`rowid` USING utf8mb4)), QUOTE(CONVERT(`code` USING utf8mb4)), QUOTE(CONVERT(`libelle` USING utf8mb4)), QUOTE(CONVERT(`nbjour` USING utf8mb4)), QUOTE(CONVERT(`type_cdr` USING utf8mb4)), QUOTE(CONVERT(`decalage` USING utf8mb4)), QUOTE(CONVERT(`active` USING utf8mb4)), QUOTE(CONVERT(`entity` USING utf8mb4))), ');') FROM `llx_c_payment_term`;
SELECT CONCAT('INSERT INTO `llx_bank_account` (`rowid`, `ref`, `label`, `bank`, `code_banque`, `code_guichet`, `number`, `cle_rib`, `courant`, `clos`, `entity`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`rowid` USING utf8mb4)), QUOTE(CONVERT(`ref` USING utf8mb4)), QUOTE(CONVERT(`label` USING utf8mb4)), QUOTE(CONVERT(`bank` USING utf8mb4)), QUOTE(CONVERT(`code_banque` USING utf8mb4)), QUOTE(CONVERT(`code_guichet` USING utf8mb4)), QUOTE(CONVERT(`number` USING utf8mb4)), QUOTE(CONVERT(`cle_rib` USING utf8mb4)), QUOTE(CONVERT(`courant` USING utf8mb4)), QUOTE(CONVERT(`clos` USING utf8mb4)), QUOTE(CONVERT(`entity` USING utf8mb4))), ');') FROM `llx_bank_account`;
SELECT CONCAT('INSERT INTO `llx_c_departements` (`rowid`, `code_departement`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`rowid` USING utf8mb4)), QUOTE(CONVERT(`code_departement` USING utf8mb4))), ');') FROM `llx_c_departements`;
SELECT CONCAT('INSERT INTO `llx_c_typent` (`id`, `code`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`id` USING utf8mb4)), QUOTE(CONVERT(`code` USING utf8mb4))), ');') FROM `llx_c_typent`;
SELECT CONCAT('INSERT INTO `llx_categorie` (`rowid`, `label`, `type`, `fk_parent`, `entity`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`rowid` USING utf8mb4)), QUOTE(CONVERT(`label` USING utf8mb4)), QUOTE(CONVERT(`type` USING utf8mb4)), QUOTE(CONVERT(`fk_parent` USING utf8mb4)), QUOTE(CONVERT(`entity` USING utf8mb4))), ');') FROM `llx_categorie`;
SELECT CONCAT('INSERT INTO `llx_categorie_fournisseur` (`fk_categorie`, `fk_soc`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`fk_categorie` USING utf8mb4)), QUOTE(CONVERT(`fk_soc` USING utf8mb4))), ');') FROM `llx_categorie_fournisseur`;
SELECT CONCAT('INSERT INTO `llx_categorie_product` (`fk_categorie`, `fk_product`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`fk_categorie` USING utf8mb4)), QUOTE(CONVERT(`fk_product` USING utf8mb4))), ');') FROM `llx_categorie_product`;
SELECT CONCAT('INSERT INTO `llx_c_units` (`rowid`, `code`, `label`, `active`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`rowid` USING utf8mb4)), QUOTE(CONVERT(`code` USING utf8mb4)), QUOTE(CONVERT(`label` USING utf8mb4)), QUOTE(CONVERT(`active` USING utf8mb4))), ');') FROM `llx_c_units`;
SELECT CONCAT('INSERT INTO `llx_product` (`rowid`, `ref`, `label`, `fk_product_type`, `fk_unit`, `customcode`, `fk_country`, `seuil_stock_alerte`, `tobatch`, `tosell`, `tobuy`, `entity`, `tms`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`rowid` USING utf8mb4)), QUOTE(CONVERT(`ref` USING utf8mb4)), QUOTE(CONVERT(`label` USING utf8mb4)), QUOTE(CONVERT(`fk_product_type` USING utf8mb4)), QUOTE(CONVERT(`fk_unit` USING utf8mb4)), QUOTE(CONVERT(`customcode` USING utf8mb4)), QUOTE(CONVERT(`fk_country` USING utf8mb4)), QUOTE(CONVERT(`seuil_stock_alerte` USING utf8mb4)), QUOTE(CONVERT(`tobatch` USING utf8mb4)), QUOTE(CONVERT(`tosell` USING utf8mb4)), QUOTE(CONVERT(`tobuy` USING utf8mb4)), QUOTE(CONVERT(`entity` USING utf8mb4)), QUOTE(CONVERT(`tms` USING utf8mb4))), ');') FROM `llx_product`;
SELECT CONCAT('INSERT INTO `llx_product_extrafields` (`fk_object`, `elev_garantia`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`fk_object` USING utf8mb4)), QUOTE(CONVERT(`elev_garantia` USING utf8mb4))), ');') FROM `llx_product_extrafields`;
SELECT CONCAT('INSERT INTO `llx_product_fournisseur_price` (`rowid`, `fk_product`, `fk_soc`, `ref_fourn`, `quantity`, `fk_unit`, `entity`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`rowid` USING utf8mb4)), QUOTE(CONVERT(`fk_product` USING utf8mb4)), QUOTE(CONVERT(`fk_soc` USING utf8mb4)), QUOTE(CONVERT(`ref_fourn` USING utf8mb4)), QUOTE(CONVERT(`quantity` USING utf8mb4)), QUOTE(CONVERT(`fk_unit` USING utf8mb4)), QUOTE(CONVERT(`entity` USING utf8mb4))), ');') FROM `llx_product_fournisseur_price`;
SELECT CONCAT('INSERT INTO `llx_entrepot` (`rowid`, `ref`, `label`, `lieu`, `statut`, `fk_parent`, `entity`) VALUES (', CONCAT_WS(',', QUOTE(CONVERT(`rowid` USING utf8mb4)), QUOTE(CONVERT(`ref` USING utf8mb4)), QUOTE(CONVERT(`label` USING utf8mb4)), QUOTE(CONVERT(`lieu` USING utf8mb4)), QUOTE(CONVERT(`statut` USING utf8mb4)), QUOTE(CONVERT(`fk_parent` USING utf8mb4)), QUOTE(CONVERT(`entity` USING utf8mb4))), ');') FROM `llx_entrepot`;
COMMIT;
